import{_ as o,o as t,c as a,a5 as d}from"./chunks/framework.CXvGqWf0.js";const u=JSON.parse('{"title":"漫画 · 第 21 话 原生造好的轮子：少写一千行（HTML 篇完结）","description":"","frontmatter":{},"headers":[],"relativePath":"comics/html/EP.21-pro-tips.md","filePath":"comics/html/EP.21-pro-tips.md","lastUpdated":1793421609000}'),r={name:"comics/html/EP.21-pro-tips.md"};function l(i,e,c,n,h,s){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="漫画-·-第-21-话-原生造好的轮子-少写一千行-html-篇完结" tabindex="-1">漫画 · 第 21 话 原生造好的轮子：少写一千行（HTML 篇完结） <a class="header-anchor" href="#漫画-·-第-21-话-原生造好的轮子-少写一千行-html-篇完结" aria-label="Permalink to &quot;漫画 · 第 21 话 原生造好的轮子：少写一千行（HTML 篇完结）&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/html/10-pro-tips">docs/html/10-pro-tips.md</a> ｜ 原画：<a href="./EP.21-pro-tips.svg">EP.21-pro-tips.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，维护着一个几百行的自制模态框：遮罩、滚动锁、Tab 焦点循环、ESC、aria-modal 各写一遍还总出 bug；下拉提示又引了一整个定位库；列表渲染用 <code>innerHTML +=</code> 拼接，被安全同学提了存储型 XSS。</li><li><strong>标签君</strong>：HTML5 结构师，本话主角，也是全篇收官人。掏出浏览器原生造好的轮子：dialog、Popover、inert、template，以及一批&quot;写对属性就生效&quot;的资源优化能力。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>前 20 话讲的是大块头能力，这一话补另一类高频但零散的轮子：过去需要大量 JS 手写、如今浏览器原生内建。共同心法只有一句——<strong>能写属性解决的别写 JS，能用浏览器保证质量的别自己重造</strong>。弹层进 Top Layer、模板天然防 XSS、资源提示写在 link 上，样板代码一片片消失。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>成熟的自定义模态要翻三座大山：遮罩层与背景滚动锁、焦点陷阱（Tab 循环、关闭后焦点归还）、ESC 与 aria-modal；浮层还要自己算定位、处理&quot;点外面关闭&quot;。再加上 <code>innerHTML +=</code> 拼接用户数据是存储型 XSS 的头号入口。z-index 大战、被父容器 overflow 裁切、焦点跑丢轮番上演。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>钥匙是<strong>顶层（Top Layer）</strong>：浏览器维护一个脱离普通层叠上下文的特殊渲染层，置顶于所有 z-index 之上，父容器裁不掉也盖不住。三件套：①<code>&lt;dialog&gt;.showModal()</code> 打开即进顶层，内建 <code>::backdrop</code> 遮罩、Tab 焦点陷阱、关闭自动归还焦点、ESC 关；<code>&lt;form method=&quot;dialog&quot;&gt;</code> 提交不发请求而是关框并把按钮 value 写入 <code>returnValue</code>；<code>show()</code> 是非模态版，适合侧栏。②<strong>Popover API</strong>：<code>popovertarget</code> 属性让按钮零 JS 控制浮层，light dismiss（点外部/ESC）自动关，<code>:popover-open</code> 挂进场动画；auto 单组互斥适合菜单，manual 可堆叠适合 Toast。③<strong>inert</strong>：给容器加上后整棵子树不可点、不可聚焦、读屏器不可见——模态打开时一行属性锁死背景。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>安全渲染：<code>&lt;template&gt;</code> 内容是惰性 DocumentFragment，不渲染、脚本不执行、图片不加载，需要时 <code>cloneNode(true)</code> 取出，用 <code>textContent/createTextNode</code> 填用户数据——文本永远是文本，不可能被解析成 <code>&lt;img onerror&gt;</code>；行为绑定靠 data-* + 事件委托。资源优化大多只需属性：资源提示五兄弟 <code>dns-prefetch → preconnect → preload（当前页确定要用）→ prefetch（下一页可能用）→ modulepreload</code>，preconnect 最多 3~4 个关键域；<code>loading=&quot;lazy&quot;</code>、<code>decoding=&quot;async&quot;</code> 延迟非首屏图片；<code>&lt;img width height&gt;</code> 让浏览器预留默认宽高比，配合 <code>height:auto</code> 是消灭 CLS 成本最低的手段。移动端 <code>inputmode=&quot;numeric|decimal&quot;</code> 直接弹数字/小数键盘、<code>enterkeyhint=&quot;search&quot;</code> 把回车变&quot;搜索&quot;——它们只改键盘不改值类型，金额、验证码场景优先于 type=&quot;number&quot;。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>showModal 内建焦点陷阱/ESC/遮罩且进顶层；Popover 零 JS + light dismiss；inert 一行锁背景。</li><li>template + cloneNode + textContent 渲染用户数据，结构与数据分离天然防 XSS。</li><li>能写属性解决的别写 JS：lazy/decoding、width/height 防 CLS、五类资源提示、inputmode。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：用 <code>&lt;dialog&gt;</code> 做&quot;确认/取消&quot;框，为什么可以不写任何状态变量就知道用户点了哪个按钮？直接给 dialog 加 <code>open</code> 属性打开，为什么又得不到这些能力？</p><p><strong>答</strong>：在 dialog 内放 <code>&lt;form method=&quot;dialog&quot;&gt;</code>，点提交按钮不会发生网络提交，而是直接关闭对话框，并把提交按钮的 <code>value</code> 写入 <code>dialog.returnValue</code>；随后触发的 <code>close</code> 事件里读 <code>returnValue</code>（如 <code>&quot;ok&quot;</code> / <code>&quot;cancel&quot;</code>）即可分支——二态结果由浏览器替你传递，无需自建变量。但 <code>returnValue</code>、焦点陷阱、ESC、<code>::backdrop</code> 这些都只属于 <code>showModal()</code>（或 <code>show()</code>）的运行时行为；直接在标签上写 <code>open</code> 属性只是让它按普通元素显示出来，既不进顶层、也没有遮罩和焦点管理——所以打开弹框必须调方法，不要手动操作 open 属性。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>dialog 模态全流程：showModal + method=dialog + 焦点陷阱 + ::backdrop + 点遮罩关闭：<a href="./../../examples/html/10-pro-tips/index-01-dialog-modal.html">examples/html/10-pro-tips/index-01-dialog-modal.html</a></li><li>Popover 三种触发 + :popover-open 动画 + light dismiss + inert 锁背景：<a href="./../../examples/html/10-pro-tips/index-02-popover-inert.html">index-02-popover-inert.html</a></li><li>template + cloneNode 列表渲染 + innerHTML XSS 对比 + data-* 委托：<a href="./../../examples/html/10-pro-tips/index-03-template-render.html">index-03-template-render.html</a></li><li>lazy/decoding/fetchpriority/防 CLS + 资源提示速查 + inputmode/enterkeyhint：<a href="./../../examples/html/10-pro-tips/index-04-resource-hints.html">index-04-resource-hints.html</a></li></ul><h2 id="全篇收束" tabindex="-1">全篇收束 <a class="header-anchor" href="#全篇收束" aria-label="Permalink to &quot;全篇收束&quot;">​</a></h2><p>21 话到此完结：CSS 篇（EP.01–11）从选择器、动画、Flex/Grid 一路到 transform 与生产技巧；HTML 篇（EP.12–21）从语义骨架、表单、Canvas/SVG，到存储、Worker、定位、拖放、多媒体与原生交互轮子。像素酱、标签君和码叔的建议始终没变——先读规范与文档，让浏览器干它擅长的事，把自己的代码花在真正的业务上。霓虹墨漫画剧场，我们在下一本手册再见。</p>',22)])])}const m=o(r,[["render",l]]);export{u as __pageData,m as default};
